    let uv = (vec2f(f32(texel % resolution), f32(texel / resolution)) + 0.5) / f32(resolution);
    ray = Ray(probe.baseCell.xyz + state.offset.xyz, 0, probeRayDirection(uv), settings.x, vec4u(255,0,0,0));
